package com.pet.buscaativa;

import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.RepeatedTest;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;
import org.junit.jupiter.params.provider.ValueSource;
import org.springframework.beans.factory.annotation.Autowired;
import com.pet.buscaativa.entities.*;
import com.pet.buscaativa.entities.dto.*;
import com.pet.buscaativa.entities.enums.*;
import com.pet.buscaativa.repositories.*;

class CancellationConcurrencyTests extends CancellationRegularizationSupport {
    @Override
    int businessStatus(org.springframework.mock.web.MockHttpServletResponse response) throws Exception {
        int status = super.businessStatus(response);
        String kind = status >= 200 && status < 300 ? "CONFIRMED" : "BUSINESS";
        if (status == 409 && "Conflito de atualização.".equals(
                json.readTree(response.getContentAsString()).path("error").asText())) {
            kind = "VERSION";
        }
        System.out.printf("E5_RACE_RESPONSE status=%d kind=%s%n", status, kind);
        return status;
    }
    @Autowired GrupoTerapeuticoRepository groups;
    @Autowired SessaoGrupoRepository sessions;
    @Autowired SessaoGrupoParticipanteRepository participants;
    private int book(Paciente p,String time,Long original) throws Exception {var dto=new AgendamentoDTO(null,professional.getIdPublico(),null,p.getIdPublico(),null,null,DAY,LocalTime.parse(time).isBefore(LocalTime.NOON)?TurnoEnum.MANHA:TurnoEnum.TARDE,LocalTime.parse(time),original==null?SituacaoAtendimento.AGENDADO:SituacaoAtendimento.REMARCADO,original,null);return businessStatus(mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post("/api/agendamentos").header("Authorization","Bearer "+tokens.gerarToken(admin)).contentType("application/json").content(json.writeValueAsString(dto))).andReturn().getResponse());}
    @RepeatedTest(2) void rr19RecoveryVersusCreationKeepsExactlyOneOperationalReservation() throws Exception {var a=canceled(true);assertEquals(new RaceResult(1,1),race("E5-recover-create",List.of(()->recover(a),()->book(other,"15:00",null))));long active=tx(()->appointments.findAll().stream().filter(x->x.getUsuario().getId().equals(professional.getId())&&x.getDataAgendamento().equals(DAY)&&x.getHoraAtendimento().equals(LocalTime.of(15,0))&&Boolean.TRUE.equals(x.getOcupaVaga())).count());assertEquals(1,active);assertEquals(appointment(a.getId()).getSituacaoReserva()==SituacaoReserva.CANCELADA?0:1,regularizations.countByAgendamento_IdAndTipoRegularizacao(a.getId(),"RECUPERACAO_RESERVA"));}
    @RepeatedTest(2) void recoveryVersusAnotherRecoveryProducesOneLedgerEntry() throws Exception {var a=canceled(true);assertEquals(new RaceResult(1,1),race("E5-recover-recover",List.of(()->recover(a),()->recover(a))));assertEquals(1,regularizations.countByAgendamento_IdAndTipoRegularizacao(a.getId(),"RECUPERACAO_RESERVA"));assertEquals(a.getVersion()+1,appointment(a.getId()).getVersion());}
    @RepeatedTest(2) void recoveryVersusRemarcationHasOnlyAValidP05Successor() throws Exception {var a=canceled(true);var r=race("E5-recover-reschedule",List.of(()->recover(a),()->book(patient,"16:00",a.getId())));assertTrue(r.equals(new RaceResult(1,1))||r.equals(new RaceResult(2,0)));var current=appointment(a.getId());assertTrue(current.getSituacaoReserva()==SituacaoReserva.AGENDADA||current.getSituacaoReserva()==SituacaoReserva.SUBSTITUIDA);assertEquals(1,regularizations.countByAgendamento_IdAndTipoRegularizacao(a.getId(),"RECUPERACAO_RESERVA"));var children=tx(()->appointments.findAll().stream().filter(x->x.getAgendamentoOriginal()!=null&&x.getAgendamentoOriginal().getId().equals(a.getId())).toList());assertEquals(current.getSituacaoReserva()==SituacaoReserva.SUBSTITUIDA?1:0,children.size());}
    @RepeatedTest(2) void recoveryVersusBlockingNeverRestoresIntoBlockedAgenda() throws Exception {var a=canceled(true);assertEquals(new RaceResult(1,1),race("E5-recover-block",List.of(()->recover(a),()->businessStatus(mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post("/api/bloqueioAgenda-config").header("Authorization","Bearer "+tokens.gerarToken(admin)).contentType("application/json").content(json.writeValueAsString(new BloqueioAgendaDTO(null,professional.getIdPublico(),DAY,DAY,"Bloqueio sintético concorrente.")))).andReturn().getResponse()))));assertEquals(appointment(a.getId()).getSituacaoReserva()==SituacaoReserva.CANCELADA,blocks.isDataBloqueadaParaUsuario(professional,DAY));}
    @RepeatedTest(2) void recoveryVersusCapacityZeroNeverExceedsNewCapacity() throws Exception {var a=canceled(true);var config=exceptions.findByUsuarioAndDataAndTurno(professional,DAY,TurnoEnum.TARDE).orElseThrow();assertEquals(new RaceResult(1,1),race("E5-recover-capacity",List.of(()->recover(a),()->businessStatus(mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post("/api/disponibilidade-config/excecoes").header("Authorization","Bearer "+tokens.gerarToken(admin)).contentType("application/json").content(json.writeValueAsString(new DisponibilidadeExcecaoDTO(config.getId(),professional.getIdPublico(),DAY,TurnoEnum.TARDE,0)))).andReturn().getResponse()))));var cap=exceptions.findByUsuarioAndDataAndTurno(professional,DAY,TurnoEnum.TARDE).orElseThrow().getCapacidade();assertEquals(appointment(a.getId()).getSituacaoReserva()==SituacaoReserva.CANCELADA,cap==0);}
    @ParameterizedTest @CsvSource({"14:59,1,1","15:00,0,2","15:01,1,1"})
    void recoveryVersusFactualRegistrationRespectDisjointTimeWindows(String time,int ok,int denied) throws Exception {var a=canceled(true);now(DAY.atTime(LocalTime.parse(time)));assertEquals(new RaceResult(ok,denied),race("E5-recover-fact-"+time,List.of(()->recover(a),()->factual(a,FrequenciaAssistencial.PRESENTE))));assertTrue(regularizations.countByAgendamento_IdAndTipoRegularizacao(a.getId(),"RECUPERACAO_RESERVA")+regularizations.countByAgendamento_IdAndTipoRegularizacao(a.getId(),"REGISTRO_FATO_ASSISTENCIAL")<=1);}
    @RepeatedTest(2) void twoFactualRequestsHaveOneCanonicalConclusion() throws Exception {var a=canceled(false);assertEquals(new RaceResult(1,1),race("E5-fact-fact",List.of(()->factual(a,FrequenciaAssistencial.PRESENTE),()->factual(a,FrequenciaAssistencial.FALTOU))));assertEquals(1,regularizations.countByAgendamento_IdAndTipoRegularizacao(a.getId(),"REGISTRO_FATO_ASSISTENCIAL"));assertEquals(a.getVersion()+1,appointment(a.getId()).getVersion());assertEquals(SituacaoReserva.CANCELADA,appointment(a.getId()).getSituacaoReserva());}
    @RepeatedTest(2) void factualVersusCorrectionWithOldVersionCannotLoseFirstFact() throws Exception {var a=canceled(false);assertEquals(new RaceResult(1,1),race("E5-fact-correct",List.of(()->factual(a,FrequenciaAssistencial.PRESENTE),()->correct(admin,a,FrequenciaAssistencial.FALTOU))));assertCanceledFact(a,FrequenciaAssistencial.PRESENTE);assertEquals(0,corrections.findByAgendamento_IdAndUnidade(a.getId(),"CAPS:CAPS_AD",org.springframework.data.domain.Pageable.unpaged()).getTotalElements());}
    @RepeatedTest(2) void factualVersusAdministrativeCancelDoesNotEraseFact() throws Exception {var a=canceled(false);var r=race("E5-fact-cancel",List.of(()->factual(a,FrequenciaAssistencial.PRESENTE),()->businessStatus(mvc.perform(patch("/api/agendamentos/"+a.getId()+"/status").param("novoStatus","CANCELADO").header("Authorization","Bearer "+tokens.gerarToken(admin))).andReturn().getResponse())));assertTrue(r.equals(new RaceResult(1,1))||r.equals(new RaceResult(2,0)));assertCanceledFact(a,FrequenciaAssistencial.PRESENTE);assertEquals(1,regularizations.countByAgendamento_IdAndTipoRegularizacao(a.getId(),"REGISTRO_FATO_ASSISTENCIAL"));}
    @RepeatedTest(2) void factualVersusCreationAtSamePastSlotPreservesClinicalCollisionWithoutOccupyingVacancy() throws Exception {var a=tx(()->seed(patient,professional,SituacaoAtendimento.CANCELADO,DAY,"08:00"));assertEquals(new RaceResult(1,1),race("E5-fact-create",List.of(()->factual(a,FrequenciaAssistencial.PRESENTE),()->book(other,"08:00",null))));assertEquals(SituacaoReserva.CANCELADA,appointment(a.getId()).getSituacaoReserva());assertFalse(appointment(a.getId()).getOcupaVaga());}
    @ParameterizedTest @ValueSource(booleans={true,false})
    void factualVersusExistingConflictingGroupConfirmationIsConsistent(boolean samePatient) throws Exception {var a=tx(()->seed(patient,professional,SituacaoAtendimento.CANCELADO,DAY,"08:00"));var member=samePatient?patient:other;var s=tx(()->{var g=new GrupoTerapeutico();g.setCoordenador(samePatient?colleague:professional);g.setTema("Grupo sintético concorrente");groups.saveAndFlush(g);var x=new SessaoGrupo();x.setGrupo(g);x.setDataSessao(DAY);x.setHorario(LocalTime.of(8,0));x.setStatus(StatusSessaoGrupo.AGENDADA);sessions.saveAndFlush(x);var p=new SessaoGrupoParticipante();p.setSessaoGrupo(x);p.setPaciente(member);p.setStatusPresenca(StatusPresencaGrupo.NAO_REGISTRADA);participants.saveAndFlush(p);return x;});var dto=new ConfirmarOcorrenciaGrupoDTO(true,List.of(new FrequenciaParticipanteGrupoDTO(member.getIdPublico(),StatusPresencaGrupo.PRESENTE)),null,s.getVersion());assertEquals(new RaceResult(1,1),race("E5-fact-group",List.of(()->factual(a,FrequenciaAssistencial.PRESENTE),()->businessStatus(mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post("/api/grupos/sessoes/"+s.getId()+"/confirmacao-ocorrencia").header("Authorization","Bearer "+tokens.gerarToken(admin)).contentType("application/json").content(json.writeValueAsString(dto))).andReturn().getResponse()))));assertEquals(StatusSessaoGrupo.REALIZADA,sessions.findById(s.getId()).orElseThrow().getStatus());assertCanceledFact(a,FrequenciaAssistencial.NAO_REGISTRADA);assertEquals(0,regularizations.countByAgendamento_IdAndTipoRegularizacao(a.getId(),"REGISTRO_FATO_ASSISTENCIAL"));}
    @RepeatedTest(2) void recoveryVersusRemovingAvailabilityKeepsOfferConsistent() throws Exception {
        var a=canceled(true);var config=exceptions.findByUsuarioAndDataAndTurno(professional,DAY,TurnoEnum.TARDE).orElseThrow();
        assertEquals(new RaceResult(1,1),race("E5-recover-remove-offer",List.of(()->recover(a),()->{var r=mvc.perform(delete("/api/disponibilidade-config/excecoes/"+config.getId()).header("Authorization","Bearer "+tokens.gerarToken(admin))).andReturn().getResponse();int code=businessStatus(r);return code==204?200:code;})));
        assertEquals(appointment(a.getId()).getSituacaoReserva()!=SituacaoReserva.CANCELADA,exceptions.findById(config.getId()).isPresent());
    }
}
